#!/usr/bin/env python3
"""Thin runtime-proposer adapter.

Selection, soak, and risk policy live in maintenance.py. This entry point
reads `.python-version`, optionally a fixture, and prints a JSON result.
It never merges, never rewrites README/history, and treats missing optional
docs as success for production copies.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import tempfile
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Mapping, Sequence

SCRIPTS_DIR = Path(__file__).resolve().parent
if str(SCRIPTS_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPTS_DIR))

import maintenance  # noqa: E402
import maintenance_common  # noqa: E402

REPO_ROOT = maintenance.REPO_ROOT


def rewrite_pin(path: Path, new_version: str) -> None:
    path.write_text(f"{new_version}\n", encoding="utf-8")


def optional_docs_present(profile: dict, root: Path) -> bool:
    docs = profile.get("optional_docs") or []
    return all((root / rel).exists() for rel in docs)


# Release-age authority for the next-minor soak.
#
# This is python.org's own downloads API, because it publishes the date upstream
# actually released a CPython version. The setup-python versions-manifest.json is
# deliberately NOT treated as the authority: it is generated by the
# actions/python-versions archive pipeline, so its timestamps can record when an
# archive was rebuilt rather than when the release happened. Letting a rebuilt
# archive redefine the age would let a freshly repackaged old release look young,
# or an old release look new, and the 30-day soak would measure the wrong thing.
#
# Unknown age never becomes "up to date" and never bypasses the soak: an
# unresolvable date is left absent so select_python_candidate defers.
RELEASE_DATE_API = "https://www.python.org/api/v2/downloads/release/"
RELEASE_DATE_MAX_PAGES = 3
RELEASE_DATE_TIMEOUT = 10
RELEASE_DATE_CACHE_TTL_SECONDS = 86400
_RELEASE_NAME_RE = re.compile(r"^Python\s+(\d+\.\d+\.\d+)\s*$")


def _default_release_date_cache() -> Path:
    override = os.environ.get("PYTHON_RELEASE_DATE_CACHE")
    if override:
        return Path(override)
    return Path(tempfile.gettempdir()) / "python-release-dates.json"


def _read_release_date_cache(path: Path, now: datetime) -> dict[str, str] | None:
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if not isinstance(raw, dict):
        return None
    fetched = maintenance_common.parse_iso_date(str(raw.get("fetched_at") or ""))
    dates = raw.get("dates")
    if fetched is None or not isinstance(dates, dict):
        return None
    if (now - fetched).total_seconds() > RELEASE_DATE_CACHE_TTL_SECONDS:
        return None
    return {str(k): str(v) for k, v in dates.items() if isinstance(v, str)}


def fetch_release_dates(
    *,
    opener: Any | None = None,
    max_pages: int = RELEASE_DATE_MAX_PAGES,
    timeout: int = RELEASE_DATE_TIMEOUT,
    cache_path: Path | None = None,
    now: datetime | None = None,
) -> tuple[dict[str, str], str, str]:
    """Return (version -> ISO date, state, detail) from the release authority.

    state is "cache" or "ok" when dates were obtained, and "unavailable" when the
    authority could not be reached or returned nothing usable. Bounded by
    max_pages requests and a per-request timeout. Every returned date is parsed
    before it is accepted, so a malformed upstream value is discarded rather than
    trusted.
    """
    now = now or datetime.now(timezone.utc)
    cache_path = cache_path or _default_release_date_cache()
    cached = _read_release_date_cache(cache_path, now)
    if cached:
        return cached, "cache", str(cache_path)

    request = opener or urllib.request.urlopen
    dates: dict[str, str] = {}
    last_error = "no-records"
    for page in range(1, max(1, int(max_pages)) + 1):
        url = f"{RELEASE_DATE_API}?is_published=true&page={page}&page_size=100"
        try:
            with request(url, timeout=timeout) as response:
                payload = json.loads(response.read().decode("utf-8"))
        except Exception as exc:  # network, timeout, JSON or HTTP error
            if not dates:
                return {}, "unavailable", f"{type(exc).__name__}: {exc}"
            break
        records = payload.get("results") if isinstance(payload, dict) else payload
        if not isinstance(records, list) or not records:
            break
        for record in records:
            if not isinstance(record, dict):
                continue
            match = _RELEASE_NAME_RE.match(str(record.get("name") or "").strip())
            if not match:
                continue
            parsed = maintenance_common.parse_iso_date(str(record.get("release_date") or ""))
            if parsed is None:
                continue
            # First publication wins: the API can list re-release records, and the
            # soak must run from the original upstream release.
            dates.setdefault(match.group(1), parsed.date().isoformat())
        last_error = ""
        if not (isinstance(payload, dict) and payload.get("next")):
            break
    if not dates:
        return {}, "unavailable", last_error or "no-parseable-records"
    try:
        cache_path.write_text(
            json.dumps({"fetched_at": now.isoformat(), "dates": dates}, sort_keys=True),
            encoding="utf-8",
        )
    except OSError:
        pass  # a cache that cannot be written is not a failure of the lookup
    return dates, "ok", f"{len(dates)} releases"


def apply_release_dates(
    manifest: Sequence[Mapping[str, Any]],
    dates: Mapping[str, str],
    state: str,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Attach authoritative dates, reporting what was resolved and what was not.

    Only the authority fills a date. A manifest that already carries one is left
    alone, and a version the authority does not list is reported as unknown and
    stays without a date, so the selector defers instead of guessing.
    """
    enriched: list[dict[str, Any]] = []
    resolved: list[str] = []
    unknown: list[str] = []
    for entry in manifest:
        if not isinstance(entry, dict):
            continue
        item = dict(entry)
        version = str(item.get("version") or "").strip()
        if item.get("release_date") or item.get("published_at"):
            enriched.append(item)
            continue
        authoritative = dates.get(version)
        if authoritative:
            item["release_date"] = authoritative
            item["release_date_source"] = "python.org-downloads-api"
            resolved.append(version)
        elif version:
            unknown.append(version)
        enriched.append(item)
    return enriched, {
        "authority": "python.org downloads API v2",
        "state": state,
        "resolved": sorted(resolved),
        "unknown": sorted(unknown),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--fixture", help="side-effect-free JSON fixture")
    parser.add_argument("--manifest", help="setup-python versions-manifest.json")
    parser.add_argument(
        "--release-date-cache",
        default="",
        help="cache file for authoritative upstream release dates",
    )
    parser.add_argument("--force", default="")
    parser.add_argument("--soak-days", type=int, default=0)
    parser.add_argument("--ignore-soak", action="store_true")
    parser.add_argument("--profile", default=str(maintenance.DEFAULT_PROFILE))
    parser.add_argument("--root", default=str(REPO_ROOT))
    parser.add_argument("--write-pin", action="store_true", help="rewrite .python-version only")
    parser.add_argument("--candidate", default="", help="with --write-pin, the version to write")
    args = parser.parse_args(argv)

    profile = maintenance.load_profile(args.profile)
    root = Path(args.root)
    pin_rel = str(profile.get("python", {}).get("pin_file") or ".python-version")
    pin_path = root / pin_rel

    if args.write_pin:
        version = args.candidate or (json.loads(Path(args.fixture).read_text(encoding="utf-8")).get("candidate") if args.fixture else "")
        if not version:
            print("write-pin requires --candidate", file=sys.stderr)
            return 2
        maintenance.parse_version(version)
        rewrite_pin(pin_path, version)
        print(json.dumps({"status": "rewritten", "candidate": version, "file": pin_rel}))
        return 0

    if args.fixture:
        data = json.loads(Path(args.fixture).read_text(encoding="utf-8"))
        current = maintenance.parse_version(str(data.get("current") or pin_path.read_text(encoding="utf-8")))
        result = maintenance.select_python_candidate(
            current,
            data.get("manifest") or [],
            soak_days=int(data.get("soak_days") or profile.get("python", {}).get("soak_days_default") or 30),
            now=maintenance_common.parse_iso_date(data.get("now")) or datetime.now(timezone.utc),
            ignore_soak=bool(data.get("ignore_soak")),
            force=data.get("force"),
        )
        result["docs_missing_ok"] = not bool(list(profile.get("optional_docs") or [])) or True
        result["optional_docs_present"] = optional_docs_present(profile, root)
        json.dump(result, sys.stdout, indent=2)
        sys.stdout.write("\n")
        return 0

    if args.manifest:
        manifest = json.loads(Path(args.manifest).read_text(encoding="utf-8"))
        current = maintenance.read_pin(pin_path)
        soak = args.soak_days or int(profile.get("python", {}).get("soak_days_default") or 30)
        # The setup-python manifest carries no upstream release dates, so the
        # next-minor soak has nothing to measure against unless they are fetched
        # from the release authority. A lookup that fails leaves the dates absent
        # and the selector defers; it never silently reads as up to date.
        dates, date_state, date_detail = fetch_release_dates(
            cache_path=Path(args.release_date_cache) if args.release_date_cache else None
        )
        manifest, date_report = apply_release_dates(manifest, dates, date_state)
        date_report["detail"] = date_detail
        result = maintenance.select_python_candidate(
            current,
            manifest,
            soak_days=soak,
            ignore_soak=args.ignore_soak,
            force=args.force or None,
        )
        result["release_dates"] = date_report
        result["optional_docs_present"] = optional_docs_present(profile, root)
        json.dump(result, sys.stdout, indent=2)
        sys.stdout.write("\n")
        return 0

    print("live proposer requires --fixture or --manifest; refusing implicit GitHub writes", file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())
